package com.bank.realtime.poll;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.context.request.async.DeferredResult;
import java.util.Map;
import java.util.concurrent.*;

@RestController
@RequestMapping("/api/v1/transfers")
public class StatusController {

    private static final Logger log = LoggerFactory.getLogger(StatusController.class);
    private final ConcurrentMap<String, DeferredResult<Map<String, String>>> waiters =
            new ConcurrentHashMap<>();

    // SHORT POLLING: client asks repeatedly; server answers immediately,
    // usually "PENDING". Simple but wasteful.
    @GetMapping("/{id}/status-short")
    public Map<String, String> shortPoll(@PathVariable String id) {
        return Map.of("transferId", id, "status", currentStatus(id));
    }

    // LONG POLLING: server HOLDS the request until the status changes or a
    // timeout fires, then responds. Fewer empty responses, lower latency.
    @GetMapping("/{id}/status-long")
    public DeferredResult<Map<String, String>> longPoll(@PathVariable String id) {
        DeferredResult<Map<String, String>> result =
                new DeferredResult<>(30000L, Map.of("transferId", id, "status", "TIMEOUT"));
        waiters.put(id, result);
        result.onCompletion(() -> waiters.remove(id));
        log.info("Long-poll registered for {}", id);
        return result;
    }

    // Called when a transfer clears — completes any waiting long-poll request.
    public void onCleared(String id) {
        DeferredResult<Map<String, String>> waiter = waiters.get(id);
        if (waiter != null) {
            waiter.setResult(Map.of("transferId", id, "status", "COMPLETED"));
        }
    }

    private String currentStatus(String id) { return "PENDING"; }
}
```

