package com.bank.realtime.sse;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import java.io.IOException;

// SSE: ONE-WAY server→client stream over a single HTTP connection. The
// EventSource client reconnects automatically. Perfect for a price ticker.
@RestController
@RequestMapping("/api/v1/market")
public class PriceStreamController {

    private static final Logger log = LoggerFactory.getLogger(PriceStreamController.class);

    @GetMapping(value = "/prices/{symbol}", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter streamPrices(@PathVariable String symbol) {
        SseEmitter emitter = new SseEmitter(0L);    // never times out
        // A background task pushes prices as they change; client only listens.
        Thread.ofVirtual().start(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    long price = 245000 + i * 50;
                    emitter.send(SseEmitter.event().name("price")
                            .data("{\"symbol\":\"" + symbol + "\",\"pricePaise\":" + price + "}"));
                    Thread.sleep(1000);
                }
                emitter.complete();
            } catch (IOException | InterruptedException e) {
                emitter.completeWithError(e);
            }
        });
        log.info("SSE price stream opened for {}", symbol);
        return emitter;
    }
}
